function validate(input) {
  const [{ Delivery = [] }] = input;
  const ids = new Set(), date = /^\d{4}-\d{2}-\d{2}$/;
  for (const [id, customer, ordered, preferred] of Delivery) {
    if (id === null || customer === null) return 'Every order needs a delivery_id and a customer_id.';
    if (ids.has(id)) return `delivery_id ${id} appears twice in Delivery.`;
    ids.add(id);
    if (typeof ordered !== 'string' || !date.test(ordered) || typeof preferred !== 'string' || !date.test(preferred)) return `Order ${id} needs dates like 2019-08-01.`;
    if (preferred < ordered) return `Order ${id} prefers delivery before it was ordered.`;
  }
  return null;
}

