function generate(rand, size) {
  const small = size === 'small';
  const day = (base, offset) => new Date(Date.parse(`${base}T00:00:00Z`) + offset * 86400000).toISOString().slice(0, 10);
  const Delivery = [];
  const add = order => {
    const preferred = rand() < 0.5 ? order : day(order, 1 + Math.floor(rand() * 14));
    Delivery.push([Delivery.length + 1, 1 + Math.floor(rand() * (small ? 4 : 300)), order, preferred]);
  };
  if (small) {
    const dates = ['2019-08-01', '2019-08-02', '2019-12-31'];
    const count = Math.floor(rand() * 9);
    for (let i = 0; i < count; i++) add(dates[Math.floor(rand() * dates.length)]);
  } else {
    // Each day gets 1 to 20 orders, so a day's percentage has a short decimal expansion or a clear rounding.
    for (let d = 0; d < 150 && Delivery.length < 2000; d++) {
      const order = day('2019-01-01', d), count = 1 + Math.floor(rand() * 20);
      for (let i = 0; i < count && Delivery.length < 2000; i++) add(order);
    }
    for (let i = Delivery.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Delivery[i], Delivery[j]] = [Delivery[j], Delivery[i]]; }
  }
  return [{ Delivery }];
}
